users = list_users({})
user_ids = for u in users { return u.id }
dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]
// For each user and date, get availability concurrently
avails = for u in user_ids {
  by_date = for d in dates {
    a = boundary retry 2 { return get_availability({ user_id: u, date: d }) } catch err {
      return fail("AVAIL", err.code + ": " + err.message)
    }
    return { date: d, busy: a.busy if a.busy != null else [] }
  }
  return { user_id: u, days: by_date }
}
return { users: user_ids, avails: avails }

// Busy intervals per user per date (minutes from 00:00)
// Helper: time "HH:MM" -> minutes
parse_min = (t) => {
  parts = text.split(t, ":")
  return number.parse(parts[0]) * 60 + number.parse(parts[1])
}

users_data = json.parse(input.raw)

// Build busy as list of {start, end} in minutes for each user/date
// We need: for each date, for each candidate start 9:00-16:00 step 30, check all free

dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]
// candidate starts in minutes from midnight: 9*60=540 to 16*60=960 step 30
starts = list.range(540, 961, 30)

// Index avails: user -> date -> busy list of {s,e} minutes
by_user = fold acc = {} for u in users_data.avails {
  days = fold dacc = {} for day in u.days {
    busy_mins = for b in day.busy {
      return { s: parse_min(b.start), e: parse_min(b.end) }
    }
    return dacc + { [day.date]: busy_mins }
  }
  return acc + { [u.user_id]: days }
}

// For a slot [start, start+60), is user free on date?
// free if no busy interval overlaps [start, start+60)
is_free = (busy_list, start) => {
  end = start + 60
  overlaps = for b in busy_list {
    // overlap if b.s < end and b.e > start
    skip if not (b.s < end and b.e > start)
    return true
  }
  return overlaps == []
}

// Find earliest
result = fold found = null for d in dates {
  skip if found != null
  day_result = fold slot_found = null for st in starts {
    skip if slot_found != null
    // check all users
    all_free_flags = for uid in users_data.users {
      busy = by_user[uid][d]
      return is_free(busy, st)
    }
    // all must be true
    ok = fold a = true for f in all_free_flags { return a and f }
    if ok {
      // format times
      sh = number.floor(st / 60)
      sm = st - sh * 60
      eh = number.floor((st + 60) / 60)
      em = (st + 60) - eh * 60
      pad = (n) => {
        s = json.encode(n) // number to string roughly - use text? 
        // better manual
        return s
      }
      // use string building carefully
      shs = text.slice("0" + json.encode(sh), -2, null) // hacky
      // actually json.encode(9) is "9", need pad
      two = (n) => {
        raw = json.encode(n)
        return ("0" + raw) if text.length(raw) == 1 else raw
      }
      start_iso = d + "T" + two(sh) + ":" + two(sm) + ":00Z"
      end_iso = d + "T" + two(eh) + ":" + two(em) + ":00Z"
      return { start: start_iso, end: end_iso }
    } else {
      return null
    }
  }
  return day_result
}

return { result: result, users: users_data.users }

